//! 🛬️ Paged text receives actual original text with retained incremental append and exact closure.
use super::{PagedUtf8,PagedUtf8AppendCursor};
use crate::{NativeDecodeControl,RetirementDemand,ValueError,ErasedSnapshotRetirement,retained_clone::{RetainedCloneBinding,RetainedCloneClose,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneRef,RetainedCloneStep,retained_clone_grant_admits}};
use semio_framework_value_native_owned::native_decoding::{NativeReceive,NativeReceiver,owned::tree::{NativeValueSource,invalid,fixed,receipt,nested,child_grant,add_receipt}};
use std::mem::{ManuallyDrop,size_of};
pub struct PagedTextReceiver<I:NativeValueSource+?Sized,const N:usize>{binding:Option<RetainedCloneBinding>,append:PagedUtf8AppendCursor,output:ManuallyDrop<Option<PagedUtf8<N>>>,retirement:RetainedCloneClose,ready:bool,taken:bool,closing:bool,input:std::marker::PhantomData<fn(&I)>}
impl<I:NativeValueSource+?Sized,const N:usize> NativeReceive<I> for PagedUtf8<N>{type Receiver=PagedTextReceiver<I,N>;fn receive_birth_demand()->RetirementDemand{fixed(2*size_of::<Self::Receiver>())}fn begin_receive(g:RetainedCloneGrant)->Result<(Self::Receiver,RetainedCloneProgress),ValueError>{let d=<Self as NativeReceive<I>>::receive_birth_demand();if !retained_clone_grant_admits(g,d){return Err(invalid())}Ok((PagedTextReceiver{binding:None,append:Default::default(),output:ManuallyDrop::new(Some(Self::new())),retirement:Default::default(),ready:false,taken:false,closing:false,input:std::marker::PhantomData},receipt(d)))}}
impl<I:NativeValueSource+?Sized,const N:usize> NativeReceiver<I,PagedUtf8<N>> for PagedTextReceiver<I,N>{
 fn demands(&self,input:RetainedCloneRef<'_,I>,_:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.ready||self.taken{return Err(invalid())}if !input.check_binding(&self.binding)?{return Ok(fixed(input.binding_copy_bytes()))}nested(self.append.next_advance_demand(input.get().text()?.as_str(),self.output.as_ref().ok_or_else(invalid)?)?,size_of::<bool>())}
 fn advance(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demands(input,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}control.checkpoint()?;if let Some(p)=input.bind(&mut self.binding,g)?{return Ok(RetainedCloneStep::Progress(p))}control.charge(d.capacity_bytes)?;let p=self.append.advance(input.get().text()?.as_str(),self.output.as_mut().ok_or_else(invalid)?,child_grant(g,size_of::<bool>())).map_err(|error|{let p=error.retained_progress();error.with_retained_progress(add_receipt(p,size_of::<bool>()).unwrap_or(p))})?.progress();self.ready=self.append.complete;let p=add_receipt(p,size_of::<bool>())?;Ok(if self.ready{RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 fn output_ready(&self)->bool{self.ready&&!self.closing&&!self.taken}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid())}Ok(fixed(2*size_of::<Option<PagedUtf8<N>>>()+size_of::<bool>()))}
 fn take(&mut self,g:RetainedCloneGrant)->Result<Option<(PagedUtf8<N>,RetainedCloneProgress)>,ValueError>{let d=self.take_demand()?;if !retained_clone_grant_admits(g,d){return Ok(None)}let value=self.output.take().ok_or_else(invalid)?;self.taken=true;Ok(Some((value,receipt(d))))}
 fn begin_close(&mut self){self.closing=true;self.append.begin_close();}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if !self.append.terminal_is_empty(){return self.append.next_demand(body)}if !self.retirement.is_empty()||self.output.is_some(){return self.retirement.next_owner_demands::<PagedUtf8<N>>(self.output.is_some(),&None,body)}RetainedCloneBinding::close_demand(&self.binding,body)}
 fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.append.terminal_is_empty(){return self.append.close_step(g)}if !self.retirement.is_empty(){return self.retirement.step_granted(g)}if let Some(step)=self.retirement.begin_granted(&mut self.output,g)?{return Ok(step)}RetainedCloneBinding::close_one(&mut self.binding,g)}
 fn terminal_is_empty(&self)->bool{self.append.terminal_is_empty()&&self.output.is_none()&&self.retirement.is_empty()&&self.binding.is_none()}
}
impl<I:NativeValueSource+?Sized,const N:usize> Drop for PagedTextReceiver<I,N>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original paged text receiving requires funded closure")}}



